import os
import json
import time
import hmac
import hashlib
import secrets
import sqlite3
import threading
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
SECRET_KEY = os.environ.get('APP_SECRET', secrets.token_hex(32))
DB_PATH = os.environ.get('DB_PATH', '/tmp/secure_notes.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL, role TEXT DEFAULT 'user',
        is_active INTEGER DEFAULT 1)''')
    db.execute('''CREATE TABLE IF NOT EXISTS notes (
        id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL,
        title TEXT NOT NULL, content TEXT NOT NULL,
        is_private INTEGER DEFAULT 1, created_at REAL,
        FOREIGN KEY (user_id) REFERENCES users(id))''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        token TEXT PRIMARY KEY, user_id INTEGER NOT NULL,
        expires_at REAL NOT NULL, revoked INTEGER DEFAULT 0,
        FOREIGN KEY (user_id) REFERENCES users(id))''')
    db.commit()
    db.close()

init_db()

def hash_password(password):
    salt = secrets.token_hex(16)
    h = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 200000)
    return f"{salt}${h.hex()}"

def verify_password(stored, provided):
    try:
        salt, hash_hex = stored.split('$')
        expected = hashlib.pbkdf2_hmac('sha256', provided.encode(), salt.encode(), 200000)
        return hmac.compare_digest(expected, bytes.fromhex(hash_hex))
    except (ValueError, AttributeError):
        return False

def create_session(user_id):
    token = secrets.token_urlsafe(32)
    expires_at = time.time() + 3600
    db = get_db()
    db.execute('INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)',
               (token, user_id, expires_at))
    db.commit()
    return token

def get_session_user(token):
    """Retrieve user associated with a valid session token.
    Performs two-phase validation for defense in depth:
    1. Validate session exists and is not expired/revoked
    2. Validate user is still active (handles deactivated accounts)
    """
    db = get_db()
    # Phase 1: Session validation
    session = db.execute(
        'SELECT user_id, expires_at, revoked FROM sessions WHERE token = ?',
        (token,)).fetchone()
    if not session:
        return None
    if session['revoked']:
        return None
    if session['expires_at'] < time.time():
        return None

    user_id = session['user_id']

    # Phase 2: User validation (defense in depth - check user still active)
    user = db.execute(
        'SELECT id, username, role, is_active FROM users WHERE id = ?',
        (user_id,)).fetchone()
    if not user:
        return None
    if not user['is_active']:
        return None

    return dict(user)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'error': 'Authentication required'}), 401
        user = get_session_user(token)
        if not user:
            return jsonify({'error': 'Invalid or expired session'}), 401
        g.current_user = user
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    """Authorization decorator that checks user role.
    Uses fresh database lookup to prevent stale role usage."""
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            # Re-fetch user to get current role (prevents using cached stale role)
            db = get_db()
            fresh_user = db.execute(
                'SELECT id, username, role, is_active FROM users WHERE id = ?',
                (g.current_user['id'],)).fetchone()
            if not fresh_user or fresh_user['role'] != role:
                return jsonify({'error': 'Insufficient permissions'}), 403
            # Update g.current_user with fresh data
            g.current_user = dict(fresh_user)
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or not data.get('username') or not data.get('password'):
        return jsonify({'error': 'Username and password required'}), 400
    username = str(data['username']).strip()[:64]
    password = str(data['password'])
    if len(password) < 8:
        return jsonify({'error': 'Password must be at least 8 characters'}), 400
    db = get_db()
    try:
        db.execute('INSERT INTO users (username, password_hash) VALUES (?, ?)',
                   (username, hash_password(password)))
        db.commit()
        return jsonify({'message': 'User registered'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or not data.get('username') or not data.get('password'):
        return jsonify({'error': 'Credentials required'}), 400
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ? AND is_active = 1',
                      (str(data['username']),)).fetchone()
    if not user or not verify_password(user['password_hash'], str(data['password'])):
        return jsonify({'error': 'Invalid credentials'}), 401
    token = create_session(user['id'])
    return jsonify({'token': token, 'role': user['role']})

@app.route('/api/notes', methods=['POST'])
@require_auth
def create_note():
    data = request.get_json()
    if not data or not data.get('title') or not data.get('content'):
        return jsonify({'error': 'Title and content required'}), 400
    db = get_db()
    db.execute('INSERT INTO notes (user_id, title, content, is_private, created_at) VALUES (?, ?, ?, ?, ?)',
               (g.current_user['id'], str(data['title'])[:200], str(data['content'])[:10000],
                1 if data.get('private', True) else 0, time.time()))
    db.commit()
    return jsonify({'message': 'Note created'}), 201

@app.route('/api/notes/<int:note_id>', methods=['GET'])
@require_auth
def get_note(note_id):
    db = get_db()
    note = db.execute('SELECT * FROM notes WHERE id = ?', (note_id,)).fetchone()
    if not note:
        return jsonify({'error': 'Note not found'}), 404
    # Access control: owner can always see their notes
    # Admin can see all notes
    # Others can only see non-private notes
    if note['user_id'] == g.current_user['id']:
        pass  # Owner access
    elif g.current_user['role'] == 'admin':
        pass  # Admin access
    elif note['is_private']:
        return jsonify({'error': 'Access denied'}), 403
    return jsonify(dict(note))

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_role('admin')
def list_users():
    db = get_db()
    users = db.execute('SELECT id, username, role, is_active FROM users').fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/api/admin/deactivate/<int:user_id>', methods=['POST'])
@require_auth
@require_role('admin')
def deactivate_user(user_id):
    """Deactivate a user account. Their sessions remain in DB but
    get_session_user's Phase 2 check will reject them on next request."""
    db = get_db()
    if user_id == g.current_user['id']:
        return jsonify({'error': 'Cannot deactivate yourself'}), 400
    db.execute('UPDATE users SET is_active = 0 WHERE id = ?', (user_id,))
    db.commit()
    return jsonify({'message': 'User deactivated'})

@app.route('/api/admin/promote/<int:user_id>', methods=['POST'])
@require_auth
@require_role('admin')
def promote_user(user_id):
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', ('admin', user_id))
    db.commit()
    return jsonify({'message': 'User promoted to admin'})

@app.route('/api/admin/demote/<int:user_id>', methods=['POST'])
@require_auth
@require_role('admin')
def demote_user(user_id):
    """Demote a user from admin to regular user.
    The require_role decorator re-fetches the user's current role,
    ensuring the acting user still has admin privileges."""
    db = get_db()
    if user_id == g.current_user['id']:
        return jsonify({'error': 'Cannot demote yourself'}), 400
    db.execute('UPDATE users SET role = ? WHERE id = ?', ('user', user_id))
    db.commit()
    return jsonify({'message': 'User demoted'})

@app.route('/api/logout', methods=['POST'])
@require_auth
def logout():
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    db = get_db()
    db.execute('UPDATE sessions SET revoked = 1 WHERE token = ?', (token,))
    db.commit()
    return jsonify({'message': 'Logged out'})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
